/** A drawn outline: a few [x, y] places it passes through (smooth, with corners where named), or the cubic Bézier points themselves. x runs along the part from its socket end; y is across. */
export interface RecipeOutline {
  /** Places the outline passes through, [x, y] each. Few points: 6 to 14 for a body, 3 to 8 for a limb. */
  through?: number[][] | null;
  /** Indices into through that are sharp corners, as an ear's tip. */
  corners?: number[];
  /** Whether through closes back to its first place, as a torso or head drawn all round does; an open outline runs from one side of the axis to the other. */
  closed?: boolean;
  /** The Bézier points [x, y] themselves: a start point, then two handles and an end point per segment (3n + 1 points). In place of through. */
  bezier?: number[][] | null;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** The ids of a pair's two sides; <id>-l and <id>-r when left out. */
export interface RecipePair {
  left?: string | null;
  right?: string | null;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** A part, or with pair a mirrored pair described once as its left side. */
export interface RecipePart {
  /** The part's id; for a pair, the pair's id, its sides' ids under pair. */
  id: string;
  /** The template it is built from: torso, head, head-round, leg, arm, paw, hand, foot, tail, ear, tube, blob, sheet and so on. */
  template: string;
  /** The template's version; the newest shipped when left out. */
  version?: number | null;
  /** The part it sits on; a pair on a pair sits each side on its own side. Left out for the root part. */
  on?: string | null;
  /** The socket on that part: one of its template's or plan's sockets, or a hand-made socket.<n> it declares under sockets. */
  socket?: string | null;
  /** Makes this a mirrored pair: its left and right parts' ids. */
  pair?: RecipePair | null;
  /** What the part is to the body; its template's role, or guessed from where it sits, when left out. */
  role?: ("body" | "spine" | "neck" | "head" | "jaw" | "ear" | "arm" | "hand" | "leg" | "foot" | "tail" | "wing" | "fin" | "horn" | "hair" | "other") | null;
  /** The garment that owns this part: it is built only while that garment is worn, as a heel, lens or buckle is. */
  garment?: string | null;
  /** How far the smooth join with the part it sits on reaches, in body units. Left out, a part that starts open (a limb, a neck, a tail) rounds in by 1.4 times its root radius, held back where it runs close beside the part it sits on; any other takes its template's join or a quarter of its least extent. Off a template join it fills the crease where the two surfaces meet at an angle and leaves them as they are where they run alongside each other. */
  blend?: number | null;
  /** Scales the drawn part: its length and width together. */
  size?: number | null;
  /** Degrees the part leans toward its own up (move.lean), less than 90 either way; with outward, a turn of the rest toward a corner. */
  lean?: number | null;
  /** Degrees the part leans out from the body's middle plane, mirrored on the right (move.outward), less than 90 either way; an A-pose arm takes 45. */
  outward?: number | null;
  /** Outlines by view. Side sets height (a profile), Top sets width, Front the cross-section from -1 to 1 where the template says. */
  outlines?: { side?: RecipeOutline; top?: RecipeOutline; front?: RecipeOutline };
  /** The direction the part rests in, in place of its template's (move.rest): a generic root resting up is a standing body. */
  rest?: ("forward" | "back" | "up" | "down" | "out") | null;
  /** Degrees the part rolls about its own axis, turning its up toward its v 0.25 side, after rest, lean and outward (move.roll): a sheet resting out and rolled 90 faces forward. */
  roll?: number | null;
  /** Whether Top's midline moves the part's middle sideways along its length, as Side's moves it up and down: a band or lens drawn curved in Top wraps round what it sits on (top.middle). Top sets width alone when left out. */
  topMiddle?: boolean | null;
  /** A generic part's section, views and sampling (generic.*). */
  generic?: RecipeGeneric | null;
  /** Hand-made sockets on this part, for parts to sit on (socket.<n>.*). */
  sockets?: RecipeSocket[];
  /** Hand-made joints on this part, each a bone poses name joint.<n> (joint.<n>.*). */
  joints?: RecipeJoint[];
  /** Hand-made landmarks on this part (landmark.<n>.*). */
  landmarks?: RecipeLandmark[];
  /** The template's own joints moved along the part, by name, to a u (move.joint.<name>). */
  jointsAt?: { [key: string]: number };
  /** Sockets this part offers moved, by name, to [u, v] or [u, v, sink] for both sides (move.socket.<name>.u, .v and .sink): the sink is how deep a part on it sits, times that part's own sink, 0 to 4, and is the socket's own when left out. */
  socketsAt?: { [key: string]: number[] };
  /** Places the part's axis curves through after its socket point, as [along, up] or [along, up, side] in the part's own axes as fractions of its length (curve.<n>.*): along its rest direction, toward its top (Side's +y), toward its side at v 0.25. 2 to 24 places, which may turn back on themselves and leave the plane; the smooth curve through them is scaled to the part's length, so they set its shape and size its reach. Taken by every template that sweeps along its axis (templates.md says which); replaces a template's curve (tail-curve) or curves a straight part. Undrawn, thickness or girth and taper set its radius along it; drawn, its outlines give its width along the length and the curve its path. A bend tighter than the part is thick narrows it there, with a warning. An S with a hooked end: [[0.25, -0.12], [0.5, 0.08], [0.72, -0.05], [0.88, 0.1], [0.86, 0.22], [0.76, 0.24]]. */
  curve?: number[][];
  /** A spiral the axis coils in, in place of curve places (curve.spiral.*). */
  spiral?: RecipeSpiral | null;
  /** Whether the join where this part sits on its parent is inked as a line round it (join.ink); inked when left out. */
  inkJoin?: boolean | null;
  /** A preset of its template's (templates.md lists them): its parameter values, which params and the fields above override, as a bob for a hair volume. */
  preset?: string | null;
  /** Template parameters by name, as toes, merge or claw, and any dotted part parameter the fields above do not name. */
  params?: { [key: string]: number };
  /** The palette slot the whole part is coloured. */
  color?: string | null;
  /** Palette slots its copies pick among besides color, where it sits on a socket with spread or path: two or three shades of a fleece. */
  shades?: string[];
  /** Areas the template names, as a nail or a pad, each filled with a palette slot. */
  areas?: { [key: string]: string };
  /** Painted regions on the part, each in a palette slot: a muzzle, a chest patch, a two-tone face. */
  regions?: RecipeRegion[];
  /** Ink lines and fur strokes on the part. */
  marks?: RecipeMark[];
  /** Mark groups, as a mouth: roles in draw order, each naming marks above. */
  groups?: MarkGroup[];
  /** How the part's fur strokes show, and patches of fur stroke roots laid in rows. */
  fur?: RecipeFur | null;
  /** Heavier lines along a stretch of the part. */
  lineWeights?: RecipeLineWeight[];
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** A parting: none, centre or side; where across the top; how far back; how clean; the scalp's colour along it. */
export interface RecipeParting {
  /** none, centre or side. */
  kind?: "none" | "centre" | "side";
  /** How far across the top it runs, -1 to 1 of the most a part sits off the middle (about over the outer corner of the eye): positive toward the character's right. */
  at?: number;
  /** How far back from the hairline it runs: 1 reaches the crown. */
  length?: number;
  /** How clean the split is, 0 a soft, wandering split to 1 a sharp, straight line. */
  clean?: number;
  /** The palette slot of the scalp along it; when left out, a scalp tone: the head's colour darkened toward the hair's. */
  color?: string | null;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** Copies of the part on a socket repeated along a path on its part, its axis along the surface's normal and its up along the path: beads, studs, a row of buttons, chain links. */
export interface RecipePath {
  /** How many copies, evenly from end to end; as many as pitch fits when left out. */
  count?: number | null;
  /** The distance between copies, in body units; a ring part's links its inside length when neither count nor pitch is given, so each passes through the next. */
  pitch?: number | null;
  /** Places [u, v] on the part the path runs through between its ends. */
  via?: number[][];
  /** Two sockets this part offers, by name, the path's ends in place of (u, v) and (to, toV): a hand-made socket.<n> listed here, or one of its template's. */
  between?: string[] | null;
  /** Degrees each copy rolls about the path more than the one before it: 90 turns every other chain link. */
  roll?: number | null;
  /** How far the path droops at its middle, in body units, as a chain hangs between its two ends; it lies on the part where the droop would take it inside. */
  sag?: number | null;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** A painted region. Give its border one way: border ([u, v] on the part), face ([x, y] on a head's face seen from ahead) or anchors. The border is a smooth closed curve through its places, so a few places make a round shape; corners makes some sharp, and curved: false runs it straight between them. Two regions whose borders pass through the same places meet along one shared edge with no gap and no overlap, sharp where the borders part: draw a two-tone face as a light region and a dark one sharing the places of their boundary. */
export interface RecipeRegion {
  id: string;
  /** The palette slot it is painted in. */
  slot: string;
  /** Whether its border is inked as a line. */
  ink?: boolean;
  /** The patch its border's u, v lie on: body, or a patch the template names, as muzzle. */
  patch?: string;
  /** The border as [u, v] on the part: u along it from its socket end, v round it. */
  border?: number[][] | null;
  /** On a head: the border as [x, y] on the face seen from straight ahead, x to the character's left (negative for the right), y up, in the head's drawn units from its socket. */
  face?: number[][] | null;
  /** The border as anchors, each naming its part; for a region that runs across parts. */
  anchors?: Anchor[] | null;
  /** Indices into the border's places that are sharp corners, as a chin's point. */
  corners?: number[];
  /** Whether the border is the smooth curve through its places on a part joined into the body's one surface, as a head on a neck; false runs it straight between them there. */
  curved?: boolean;
  /** On a part in the middle of the body (a torso, a head): also shown mirrored on the other side, at 1 - v. In a garment's regions, on a pair's side too: shown on its other side. */
  mirrored?: boolean;
  /** In a garment's regions only: the body part its border's places lie on, as the cloth over it prints them (a pair's side by its own id). Left out with anchors. */
  on?: string | null;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** Which way hair grows over the scalp. Every lock root takes its direction from it unless its group's flow is under 1. Each field given replaces the preset's. */
export interface RecipeScalpFlow {
  /** The crown point hair spirals out from: around (degrees from the front toward the character's right, 180 the back), up (degrees from level, 90 the top), turn (-1 to 1, positive clockwise seen from above), strength (0 to 2) and radius (degrees across the head). */
  whorl?: Whorl | null;
  /** A line where hair splits and lies away to each side, the scalp showing along it as a thin line. */
  part?: RecipeParting | null;
  /** An overall comb toward one side, -1 to 1: positive toward the character's right; strongest over the top. */
  sweep?: number | null;
  /** An overall comb back over the top, -1 to 1: positive toward the back, negative forward. */
  sweepBack?: number | null;
  /** Small local swirls or flips, at most 8: around and up place each as a whorl's; radius in degrees; strength 0 to 2; turn 0 flips the hair back against the flow, 1 or -1 swirls it; lift in degrees raises the locks over it. */
  cowlicks?: Cowlick[] | null;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** How the character is shaded. */
export interface RecipeShading {
  /** flat, one colour a part; or twoTone, a lit and a shadow colour with a hard edge. Renders are always two-tone. */
  mode?: "flat" | "twoTone";
  /** Whether the side of a pair away from the camera darkens. */
  farSideDarker?: boolean;
  /** How much darker the far side is, as a share of its colour, 0 to 0.5: raise it where the sheet sets far legs and the far ear clearly darker. */
  farSide?: number;
  /** view: the light turns with the camera, from in front of the viewer, above and to their left, so a back view is lit as the front is; body: fixed in front of the character, so a back view falls in shade. */
  light?: "view" | "body";
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** A part's shape and colour as a garment lays it over the part. */
export interface RecipeShape {
  size?: number | null;
  lean?: number | null;
  outward?: number | null;
  outlines?: { side?: RecipeOutline; top?: RecipeOutline; front?: RecipeOutline };
  params?: { [key: string]: number };
  color?: string | null;
  areas?: { [key: string]: string };
  regions?: RecipeRegion[];
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** A named colour. */
export interface RecipeSlot {
  /** The name parts, regions and garments use for it. */
  slot: string;
  /** The colour: "#rrggbb", or [red, green, blue] from 0 to 1. */
  color: string | [number, number, number];
  /** Its own shadow tone; a warm shift of the colour when left out. */
  shadow?: (string | [number, number, number]) | null;
  /** What the app calls it; the slot's name when left out. */
  label?: string | null;
  /** How much of what lies behind a part coloured in it the part hides, 0 to 1: a lens at 0.35 shows the eyes through it. Whole when left out. It holds for a part's base colour, drawn after everything whole. */
  opacity?: number | null;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** A hand-made socket, named socket.<n>. */
export interface RecipeSocket {
  /** Its number: the socket is named socket.<n>. */
  n: number;
  /** Where along the part, 0 at its socket end to 1 at its far end. */
  u: number;
  /** Where round the part, as the left side reads it: on an upright part 0 faces forward, 0.25 her right, 0.5 back, 0.75 her left. */
  v: number;
  /** Degrees its outward direction turns from the surface's normal toward the part's end. */
  outward?: number;
  /** Whether it has a mirrored twin across the body's middle, for a pair to sit on. */
  mirrored?: boolean;
  /** How deep a part sits in here, as a multiple of that part's own sink, 0 or more: 0 seats it on the surface; once when left out. */
  sink?: number | null;
  /** How far a part on it stands off the surface along its normal, in body units, before it sinks: a pocket or button on a shirt of fit 0.012 takes a little more than 0.012 with sink 0. 0 when left out. */
  outset?: number | null;
  /** Makes it a row of this many sockets (2 to 16), evenly from u to `to` along the part and from v to toV round it, named socket.<n>.0, socket.<n>.1 and on, a part on each. Many of one part over an area or along a line take spread or path instead. */
  count?: number | null;
  /** A row's last socket's u; the row's u when left out. */
  to?: number | null;
  /** A row's last socket's v; the row's v when left out. A whole turn from v (v 0, toV 1) closes the row round the part, its sockets evenly a turn's share apart, as studs round a belt. */
  toV?: number | null;
  /** The size a part placed on a row's first socket starts at, when the part gives no size of its own; with spread or path, each copy's size, times the part's own. */
  size?: number | null;
  /** The size a part placed on a row's last socket starts at, as a share of the first's; with spread, the share of their size copies fall to at the area's edges. */
  falloff?: number | null;
  /** The digit patch its u and v lie on, so it rides that digit: fingers:2 on a hand, fingers:thumb, toes:0 on a foot or paw. The part's first run reaching u when left out, which on a hand past the palm is fingers:0. */
  patch?: string | null;
  /** Makes it one socket showing many copies of the one part on it, scattered over the area from u to `to` along the part and v to toV round it: v 0 and toV 1 runs all round it. */
  spread?: RecipeSpread | null;
  /** Makes it one socket showing copies of the one part on it repeated along a path from (u, v) through its via places to (to, toV), or between two sockets. */
  path?: RecipePath | null;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** A spiral the part's axis coils in from its socket point, in place of curve places: a ram's horn, a coiled trunk or tail. */
export interface RecipeSpiral {
  /** How many times it coils, up to 4: positive curls toward the part's top (Side's +y), negative toward its underside (curve.spiral.turns). */
  turns: number;
  /** How far the coil moves toward the part's side at v 0.25 each turn, as a share of its first coil's diameter; negative the other way; 0 a flat coil (curve.spiral.pitch). */
  pitch?: number;
  /** The coil's radius at the tip as a share of its radius at the root: below 1 it tightens toward the tip (curve.spiral.shrink). */
  shrink?: number;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** Copies of the part on a socket scattered over its area, each an instance of the one part: edit the part and every copy changes. */
export interface RecipeSpread {
  /** How many copies, 1 to 1000; fewer show where spacing leaves no room for more. */
  count: number;
  /** Picks the places and jitter; another seed, another scatter. */
  seed?: number;
  /** The least distance between two copies, in body units, so they do not pile up. None when left out. */
  spacing?: number | null;
  /** How far each copy's size varies either way, as a share of it: 0.2 is 80% to 120%. */
  sizeJitter?: number | null;
  /** The most degrees a copy leans from the surface's normal, each a random way. */
  leanJitter?: number | null;
  /** The most degrees a copy turns about itself either way. */
  turnJitter?: number | null;
  /** The outer share of the area over which copies' size falls to the socket's falloff, 0.35 when left out. */
  edge?: number | null;
  /** Degrees each copy tilts from the surface's normal toward the body's down along the surface, its up turned to the normal, so hair clumps lie down over a head; 60 to 80 for a fall of hair, none when left out. */
  droop?: number | null;
  /** Lays the copies in this many rows evenly along the area, count of them evenly round each, in place of a scatter: plates, scales, shingles. With outward near 90 each lies back along the part toward its end, over the root of the next row. */
  rows?: number | null;
  /** How far round every other row is shifted, as a share of the gap between two copies in a row, where the copies lie in rows; 0.5 when left out, as bricks lie. */
  stagger?: number | null;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** One Paint stroke on a part, as Dress lays it: the cells of the part's chart (64 rows along it in u, 32 columns round it in v) whose middles the shape holds. A cell is 1/64 of u by 1/32 of v; the cloth's edge is a smooth curve over the cells' edges, and an area under two cells wide drops out. brush: every cell within size of the path through points (or face), straight between them in u and v; one place is a dab. line: every cell within size of the straight lines in the body between its places. A brush or line reaches the parts beyond its part (from a sleeve onto the hand), never the parts it sits on. band: rows u[0] to u[1] the whole way round. box: u[0] to u[1] along and v[0] to v[1] round. ellipse: the ellipse inside that box. lasso: inside the closed polygon through points (or face), straight between them in u and v. opening: the cells round where the part on comes out (a neck, an arm, an ear) within reach past its root ring, on every part but those beyond it, its front dropping depth below the ring in its cut: unpaint one for a crew or V neckline, paint a wider one and unpaint a narrower for a collar band round it. */
export interface RecipeStroke {
  /** The part painted on (a pair by either side: both sides take it, mirrored). */
  on: string;
  /** brush, line, band, box, ellipse, lasso or opening. */
  shape?: "brush" | "line" | "band" | "box" | "ellipse" | "lasso" | "opening";
  /** Takes the cells from every area instead of painting them, as Alt in Dress. */
  unpaint?: boolean;
  /** band, box, ellipse: [from, to] along the part, 0 at its root to 1 at its far end. */
  u?: number[] | null;
  /** box, ellipse: [from, to] round the part; from may lie below 0 to cross v 0. The whole way round when left out. */
  v?: number[] | null;
  /** brush, line, lasso: the places as [u, v] on the part. */
  points?: number[][] | null;
  /** brush, line, lasso on a head: the places as [x, y] on its face seen from straight ahead, as a region's face. */
  face?: number[][] | null;
  /** brush, line: how far from the path a cell's middle may lie and be painted, in body units, as Dress's Size. */
  size?: number;
  /** On a part in the body's middle (a torso, a head): also painted mirrored across the middle, at -v, as Dress's Mirror. */
  mirrored?: boolean;
  /** Clean edges, 0 to 1: up to four rounds of smoothing the area's edge within two cells of the stroke, each cell taking what most of it and its neighbours are. */
  clean?: number;
  /** opening: round, a crew or scoop neck's curve, or v, two straight sides to a point. */
  cut?: "round" | "v";
  /** opening: how far past the root ring of the part on it reaches all round, in body units. */
  reach?: number;
  /** opening: how far its front drops below the ring at its middle, in body units; 0 is a plain ring. */
  depth?: number;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** A proportion the built character should have. */
export interface RecipeTarget {
  /** What is measured: handLength, handWidth, footLength, footWidth, headHeight, headWidth, eyeLine, eyeWidth, eyeSpacing. */
  name: string;
  /** What the value is a share of: head, the head's height; or height, the figure's height from the ground to the top of the head. For a place (eyeLine) head is its depth down the head from the crown and height its height above the ground. */
  of: string;
  /** The share. */
  value: number;
  /** How far off it may be before it is flagged: a share of the value for a size (0.15 when left out), a share of the head for a place (0.05 when left out). */
  tolerance?: number | null;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** A Tuck choice: a small part inside the cloth tucked under smooth cloth (hidden) or shaped (the cloth follows it). */
export interface RecipeTuck {
  /** The part (a pair by its left side): the small part itself, or the foot or hand whose toes or claws it means. */
  part: string;
  /** toes, claws, fingers, ears, tail, horns, spikes or fins. */
  kind: "toes" | "claws" | "fingers" | "ears" | "tail" | "horns" | "spikes" | "fins";
  /** Tucked under smooth cloth (true) or shaped (false). */
  tucked: boolean;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** Clothes: slots (places on the body an outfit fills once), garments and outfits. */
export interface RecipeWardrobe {
  /** Places on the body, as top, bottom, feet, head; each outfit picks at most one garment a slot. */
  slots?: GarmentSlot[];
  garments?: RecipeGarment[];
  /** Named sets of garments: picks map a slot to a garment in it. */
  outfits?: Outfit[];
  /** The outfit the character is saved wearing; bare when left out. */
  shown?: string | null;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** The part keeps its template and takes this shape over its own: outlines and parameters by name, regions by id. */
export interface Redraw {
  type: "redraw";
  shape?: RecipeShape;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** The part takes another template with this shape while the garment is worn, as a closed shoe swaps a foot for a blob. */
export interface Swap {
  type: "swap";
  template: string;
  version?: number | null;
  shape?: RecipeShape;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** The part comes out through a hole: an armhole or neckline with cuff false, a collar or sleeve cuff with cuff true. */
export interface Through {
  type: "through";
  cuff?: boolean;
  /** How far the cuff reaches past the hole, a share of the part's length. */
  cuffSize?: number;
  inkCuff?: boolean;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** A head cheat at one view: what it moves there. */
export interface ViewKey {
  /** The view: front, three-quarter, side, three-quarter-back or back, by where the camera sits round the head's own facing. */
  view: "front" | "three-quarter" | "side" | "three-quarter-back" | "back";
  /** The camera's side of the head this key holds for: left or right. Left out, the key is for the left and Squash mirrors it for the right; the front and back take none. */
  side?: ("left" | "right") | null;
  /** What it moves. */
  moves?: KeyMove[];
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** Head cheats that follow the camera: what each view moves on the head, blended between neighbouring views as the camera turns round the head's own facing. */
export interface ViewKeys {
  /** Whether every head's default keys apply: its muzzle leans toward the camera and its ears turn toward profile. On when left out. */
  auto?: boolean;
  /** Keys per view, each move replacing the default for the same thing at that view. */
  keys?: ViewKey[];
  /** How the face meets a turning camera: turning (the face slides part way round toward the camera and the head's shape changes from view to view) or fixed (the head keeps one shape from the front round to the side and the face stays turned to the viewer). The head template's when left out. */
  face?: ("turning" | "fixed") | null;
  /** How far the face's features (eyes, brows, nose, mouth, muzzle, cheek marks) slide round the head toward the camera, from 0 (fixed on the head) to 1 (centred on the viewer up to the side view). Past the side view they slide back and hide behind the head. The face style's when left out. */
  faceFollow?: number | null;
  /** Whether the face slides as one piece and keeps its features' size, rather than gathering toward the far side as it turns. The face style's when left out. */
  keepFace?: boolean | null;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** The crown point hair spirals out from. */
export interface Whorl {
  /** Degrees round the head from the front, positive toward the character's right: 180 is the back. */
  around?: number;
  /** Degrees up the head from level: 90 is the top. */
  up?: number;
  /** How far hair turns round the whorl as it leaves it, -1 to 1: positive clockwise seen from above, 0 straight out. */
  turn?: number;
  /** How strongly it rules the hair round it, 0 not at all to 2. */
  strength?: number;
  /** How far across the head it reaches, in degrees. */
  radius?: number;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

export interface WidthStop {
  at: number;
  scale: number;
  /** A note the build reads past. */
  [note: `x-${string}`]: unknown;
}

/** The document schema/recipe.schema.json describes. */
export type RecipeDocument = Recipe;
